BEGIN;

DELETE FROM questions WHERE topic = 'The Nervous System' AND subtopic IN ('Refractory Periods', 'Repolarization & Hyperpolarization', 'Resting Membrane Potential', 'Threshold, Depolarization & Summation', 'Voltage-Gated Na+ Channels & Depolarization');

-- Q1 [Resting Membrane Potential | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub1$Resting Membrane Potential$sub1$, $qt1$A physiologist inserts a microelectrode into a neuron that is not receiving any stimulation and reads the steady transmembrane voltage on the oscilloscope. The reading that the physiologist records, along with the correct interpretation of the charge across the membrane, is:$qt1$, $op1$[{"label": "A", "text": "about -70 mV, with the inside of the neuron negative relative to the outside"}, {"label": "B", "text": "about +70 mV, with the inside of the neuron positive relative to the outside"}, {"label": "C", "text": "about +30 mV, with the inside of the neuron positive relative to the outside"}, {"label": "D", "text": "about 0 mV, with no charge difference across the membrane"}]$op1$::jsonb, 'A', $ex1$This is a Biology question that falls under the content category 'The Action Potential'. The answer is A because a neuron at rest holds a steady voltage of about -70 mV with its interior negative relative to the exterior. OpenStax Biology 2e states that "A neuron at rest is negatively charged: the inside of a cell is approximately 70 millivolts more negative than the outside (−70 mV...). This voltage is called the resting membrane potential." OpenStax Anatomy & Physiology 2e likewise reports that "the difference in charge is measured at -70 mV, the value described as the resting membrane potential," and that the convention compares the inside relative to the outside, so the value is negative. An unstimulated neuron therefore sits at this negative resting value rather than at a positive or zero voltage. (Choice A) is correct because -70 mV with an interior-negative polarity is the textbook resting membrane potential of a neuron at rest. (Choice B) keeps the correct magnitude but inverts the polarity; the inside is negative, not positive, so +70 mV is wrong. (Choice C) is the approximate peak voltage reached during depolarization, when "the membrane potential will reach +30 mV by the time sodium has entered the cell," not the resting value. (Choice D) wrongly assumes a resting cell has no transmembrane voltage, but all living cells maintain a charge difference across the membrane. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established numerical value and polarity of the neuronal resting membrane potential as defined in the source texts.$ex1$, 'easy', '3A', $cc1$The Action Potential$cc1$, 'biology', 1, 70
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a1B$correct magnitude with inverted polarity (interior positive instead of negative)$a1B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a1C$substituting the depolarization peak (+30 mV) for the resting value$a1C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a1D$assuming a cell at rest has no transmembrane voltage$a1D$ FROM q;

-- Q2 [Resting Membrane Potential | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub2$Resting Membrane Potential$sub2$, $qt2$A physiologist studying a resting neuron tracks the Na+/K+ ATPase as it hydrolyzes a single molecule of ATP to maintain the cell's ion gradients. During that one catalytic cycle, how does the pump move sodium and potassium across the membrane?$qt2$, $op2$[{"label": "A", "text": "It pumps 3 Na+ into the cell and 2 K+ out of the cell per ATP hydrolyzed."}, {"label": "B", "text": "It pumps 3 Na+ out of the cell and 2 K+ into the cell per ATP hydrolyzed."}, {"label": "C", "text": "It pumps 2 Na+ out of the cell and 3 K+ into the cell per ATP hydrolyzed."}, {"label": "D", "text": "It pumps 3 Na+ out of the cell and 3 K+ into the cell per ATP hydrolyzed."}]$op2$::jsonb, 'B', $ex2$This is a Biology question that falls under the content category 'The Action Potential'. The answer is B because the Na+/K+ ATPase moves three Na+ ions out of the cell and two K+ ions into the cell for each ATP molecule it hydrolyzes. OpenStax Anatomy & Physiology 2e states that "each Na+/K+ pump moves three Na+ ions out of the cell and two K+ ions into the cell for each ATP molecule that is used," and OpenStax Biology 2e similarly notes that "sodium potassium pumps brings two K+ ions into the cell while removing three Na+ ions per ATP consumed." Because three positive charges leave for every two that enter, the pump is electrogenic and helps keep the cell interior negative, supporting the resting membrane potential of about -70 mV. (Choice A) reverses the transport directions of both ions; the pump extrudes Na+ and imports K+, not the reverse. (Choice B) is correct because it states the actual 3 Na+ out, 2 K+ in stoichiometry per ATP. (Choice C) misassigns the 3:2 ratio to the wrong ions, since it is Na+ that moves in threes and K+ in twos, not the opposite. (Choice D) correctly extrudes Na+ but makes the pump electroneutral by moving 2 K+ as 3 K+, contradicting the documented 3:2 ratio. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established ion stoichiometry of the Na+/K+ ATPase directly from foundational physiology.$ex2$, 'easy', '3A', $cc2$The Action Potential$cc2$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a2A$Correct 3:2 numbers but both ion transport directions swapped$a2A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a2C$3:2 ratio assigned to the wrong ions (Na+ and K+ counts swapped)$a2C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a2D$Correct Na+ extrusion but treats pump as electroneutral (3:3) rather than 3:2$a2D$ FROM q;

-- Q3 [Resting Membrane Potential | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub3$Resting Membrane Potential$sub3$, $qt3$A physiologist records a neuron at its resting state and counts the open ion channels in a patch of membrane, finding many more open potassium (K+) leak channels than sodium (Na+) leak channels. Asked to explain why the cell's interior measures about -70 mV relative to the outside, the physiologist reasons from this channel count to the net movement of charge.$qt3$, $op3$[{"label": "A", "text": "Because there are far more Na+ leak channels than K+ leak channels, Na+ enters faster than K+ exits, so net positive charge enters and the interior becomes negative."}, {"label": "B", "text": "Because the equal numbers of Na+ and K+ leak channels let the two cation fluxes cancel, the unbalanced anions leave the interior negative."}, {"label": "C", "text": "Because there are far more K+ leak channels than Na+ leak channels, K+ exits faster than Na+ enters, so net positive charge leaves and the interior becomes negative."}, {"label": "D", "text": "Because the K+ leak channels let K+ flow into the cell faster than Na+ exits, the added intracellular K+ makes the interior negative."}]$op3$::jsonb, 'C', $ex3$This is a Biology question that falls under the content category 'The Action Potential'. The answer is C because a neuron's membrane carries far more potassium leak channels than sodium leak channels, so K+ diffuses out down its gradient much faster than Na+ leaks in, and the loss of net positive charge leaves the interior negative. The text states that "the neurons have far more potassium leakage channels than sodium leakage channels. Therefore, potassium diffuses out of the cell at a much faster rate than sodium leaks in," and that "Because more cations are leaving the cell than are entering, this causes the interior of the cell to be negatively charged relative to the outside of the cell." The Anatomy text echoes this, noting that "Leakage channels allow Na+ to slowly move into the cell or K+ to slowly move out," with the resting interior held near -70 mV. The physiologist's channel count (more open K+ than Na+ leak channels) thus directly predicts a net outward flow of positive charge and a negative resting potential, which the Na+/K+ pump then maintains. (Choice A) reverses which leak channel predominates, so it wrongly has net positive charge entering, which would depolarize rather than create a negative resting interior. (Choice B) is wrong because equal permeability to the two cations would not establish the K+-dominated potential the text describes; the negative interior depends on K+ permeability exceeding Na+ permeability, not on balanced fluxes. (Choice C) is correct because the predominance of K+ leak channels drives faster K+ efflux than Na+ influx, removing net positive charge so the interior becomes negative. (Choice D) misstates the direction of leak: K+ leak channels let K+ flow out of (not into) the cell down its concentration gradient, so adding intracellular K+ is not the cause of the negative interior. This is a Scientific Reasoning and Problem Solving question because it requires inferring the direction of net charge movement from a given relative channel count and connecting that flux to the sign of the resting membrane potential.$ex3$, 'medium', '3A', $cc3$The Action Potential$cc3$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a3A$Swaps which leak channel predominates while keeping the same negative-interior conclusion$a3A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a3B$Assumes balanced Na+/K+ permeability still yields a negative interior$a3B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a3D$Keeps K+-dominant idea but reverses the direction K+ leaks across the membrane$a3D$ FROM q;

-- Q4 [Resting Membrane Potential | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub4$Resting Membrane Potential$sub4$, $qt4$A physiologist measures the resting ion concentrations in a neuron and records K+ at roughly 155 mM inside the cell versus 4 mM outside, with Na+ at roughly 145 mM outside versus 12 mM inside. Considering only the concentration gradient acting on K+ as it passes through an open potassium leak channel at rest, the physiologist predicts the net direction this ion is driven.$qt4$, $op4$[{"label": "A", "text": "K+ is driven into the cell, because its concentration is far higher outside (~155 mM) than inside (~4 mM) and it diffuses down its gradient"}, {"label": "B", "text": "K+ is driven into the cell, because the Na/K pump continuously imports K+ and this dominates its movement through the leak channel"}, {"label": "C", "text": "K+ stays evenly distributed, because at rest its inside and outside concentrations are already equal"}, {"label": "D", "text": "K+ is driven out of the cell, because its concentration is far higher inside (~155 mM) than outside (~4 mM) and it diffuses down its gradient"}]$op4$::jsonb, 'D', $ex4$This is a Biology question that falls under the content category 'The Action Potential'. The answer is D because a leak channel lets an ion diffuse passively down its own concentration gradient, and the values show K+ at ~155 mM inside versus ~4 mM outside, so net diffusion through a K+ leak channel carries the ion out of the cell. The text states that \"in neurons, potassium ions are maintained at high concentrations within the cell while sodium ions are maintained at high concentrations outside of the cell,\" and that the cell \"possesses potassium and sodium leakage channels that allow the two cations to diffuse down their concentration gradient,\" with the result that \"potassium diffuses out of the cell.\" Because the intracellular concentration (~155 mM) greatly exceeds the extracellular concentration (~4 mM), the gradient points outward, and this continual K+ leak outward is precisely what helps establish the negative resting potential. (Choice A) is incorrect because it inverts the actual K+ gradient; the data show K+ is higher inside, not outside, so diffusion cannot drive it inward. (Choice B) is incorrect because the Na/K pump actually moves K+ into the cell against its gradient, but the stem restricts the prediction to passive diffusion through the leak channel, where the concentration gradient drives K+ outward. (Choice C) is incorrect because a concentration gradient for K+ clearly exists at rest—~155 mM inside versus ~4 mM outside—so the ion is not evenly distributed. (Choice D) is correct because K+ is far more concentrated inside, so diffusion through its leak channel drives it out of the cell. This is a Scientific Reasoning and Problem Solving question because it requires reading concrete concentration values from a scenario and predicting the resulting direction of passive ion movement rather than recalling a stated fact.$ex4$, 'medium', '3A', $cc4$The Action Potential$cc4$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a4A$Inverts the K+ concentration gradient, assigning the high concentration to the outside (~155 mM) and the low to the inside (~4 mM), and concludes K+ diffuses inward$a4A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a4B$Keeps the subject as K+ but attributes its movement to the Na/K pump (which does import K+, but against its gradient and not through the leak channel the stem specifies), reaching the wrong net direction for passive leak$a4B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a4C$Denies that a K+ concentration gradient exists at rest, treating the inside and outside concentrations as equal$a4C$ FROM q;

-- Q5 [Resting Membrane Potential | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub5$Resting Membrane Potential$sub5$, $qt5$A pharmacologist applies a compound to a resting neuron (Vm ~-70 mV) that selectively increases the number of open K+ leak channels in its membrane, while leaving Na+ leak channels, the Na+/K+ pump, and all voltage-gated channels untouched. Given that the K+ equilibrium potential is ~-90 mV and the Na+ equilibrium potential is ~+60 mV, the student is asked to predict how Vm will change and to justify why the resting value sat where it did.$qt5$, $op5$[{"label": "A", "text": "Vm hyperpolarizes toward ~-90 mV, because the resting membrane is far more permeable to K+ than to Na+, so adding K+ leak channels pulls Vm even closer to E_K."}, {"label": "B", "text": "Vm depolarizes toward ~0 mV, because K+ has the larger concentration gradient, so adding K+ leak channels lets more K+ enter and drives Vm toward 0 mV."}, {"label": "C", "text": "Vm stays unchanged near -70 mV, because Na+ and K+ are equally permeable at rest, so adding K+ leak channels leaves the balance of leak currents unaffected."}, {"label": "D", "text": "Vm depolarizes toward ~+60 mV, because Na+ leak dominates the resting membrane, so adding K+ leak channels pushes Vm toward E_Na."}]$op5$::jsonb, 'A', $ex5$This is a Biology question that falls under the content category 'The Action Potential'. The answer is A because the resting membrane potential sits near the K+ equilibrium potential precisely because the membrane is far more permeable to K+ than to Na+, so increasing K+ permeability drives Vm even closer to E_K. OpenStax Biology 2e states that "the negative charge within the cell is created by the cell membrane being more permeable to potassium ion movement than sodium ion movement" and that "the neurons have far more potassium leakage channels than sodium leakage channels," which is why "the difference in the number of positively charged potassium ions (K+) inside and outside the cell dominates the resting membrane potential." Because Vm is dominated by the most permeant ion, resting Vm (~-70 mV) lies close to E_K (~-90 mV) rather than E_Na (~+60 mV); adding still more open K+ channels makes the membrane even more K+-selective and pulls Vm toward E_K, hyperpolarizing the cell, consistent with OpenStax Anatomy & Physiology 2e noting that "Potassium ions reach equilibrium when the membrane voltage is below -70 mV," producing hyperpolarization. (Choice A) is correct: greater K+ permeability anchors Vm near E_K, and more K+ leak channels hyperpolarize toward ~-90 mV. (Choice B) is wrong because it correctly places Vm near E_K via the K+ gradient but predicts the opposite direction; more open K+ channels move Vm toward E_K (~-90 mV), not toward 0 mV, and the driving force on K+ is net outward, not inward. (Choice C) is wrong because the membrane is not equally permeable to Na+ and K+ at rest; the text states there are far more K+ than Na+ leak channels, so adding K+ channels does change the leak balance. (Choice D) is wrong because it reverses which ion the resting membrane is most permeable to; K+ leak dominates, not Na+ leak, so Vm sits near E_K and added K+ channels cannot push it toward E_Na. This is a Scientific Reasoning and Problem Solving question because it requires predicting the direction of a membrane-potential change from a manipulation of ion permeability and justifying it against the equilibrium potentials, rather than recalling a stated fact.$ex5$, 'hard', '3A', $cc5$The Action Potential$cc5$, 'biology', 2, 165
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a5B$Correct localization of Vm near E_K but attributes it to gradient magnitude and predicts the wrong direction of change$a5B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a5C$Assumes equal resting permeability to Na+ and K+, ignoring the dominant K+ leak$a5C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a5D$Swaps which ion the resting membrane is most permeable to and the direction Vm would move$a5D$ FROM q;

-- Q6 [Threshold, Depolarization & Summation | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub6$Threshold, Depolarization & Summation$sub6$, $qt6$At a neuromuscular junction, a presynaptic neuron releases acetylcholine, which opens Na+ channels in the postsynaptic membrane and produces an excitatory postsynaptic potential (EPSP). A student is asked to predict how this EPSP changes the likelihood that the postsynaptic neuron fires an action potential.$qt6$, $op6$[{"label": "A", "text": "It hyperpolarizes the membrane, shifting the membrane potential away from threshold and making the neuron less likely to fire an action potential."}, {"label": "B", "text": "It depolarizes the membrane, shifting the membrane potential toward threshold and making the neuron more likely to fire an action potential."}, {"label": "C", "text": "It depolarizes the membrane but shifts the membrane potential away from threshold, leaving the neuron less likely to fire an action potential."}, {"label": "D", "text": "It leaves the membrane potential unchanged but lowers the threshold value itself, so the neuron fires only after the new threshold is reached."}]$op6$::jsonb, 'B', $ex6$This is a Biology question that falls under the content category 'The Action Potential'. The answer is B because an EPSP is, by definition, a depolarization that moves the membrane potential toward threshold and therefore makes the postsynaptic neuron more likely to fire. When an excitatory neurotransmitter such as acetylcholine binds, Na+ channels open and Na+ enters the postsynaptic cell, "caus[ing] the postsynaptic membrane to depolarize. This depolarization is called an excitatory postsynaptic potential (EPSP) and makes the postsynaptic neuron more likely to fire an action potential" (Biology 2e). The companion text reinforces this: "Depolarization in a postsynaptic potential is called an excitatory postsynaptic potential (EPSP) because it causes the membrane potential to move toward threshold" (Anatomy & Physiology 2e). Threshold itself is a fixed value (about -55 mV) that the membrane potential must reach, not a value the EPSP adjusts. (Choice A) describes the inhibitory postsynaptic potential (IPSP): hyperpolarization "mak[es] the neuron less likely to fire," which is the opposite of an EPSP. (Choice B) is correct because an EPSP depolarizes the membrane toward the fixed threshold, increasing firing likelihood. (Choice C) correctly states that an EPSP depolarizes but wrongly reverses its direction relative to threshold; depolarization moves the membrane potential toward, not away from, threshold. (Choice D) confuses moving the membrane potential toward a fixed threshold with changing the threshold value, but "[a]ny depolarization that does not change the membrane potential to -55 mV or higher will not reach threshold," indicating threshold is a set point the EPSP moves toward rather than alters. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the definitional effect of an EPSP on membrane potential and firing likelihood.$ex6$, 'easy', '3A', $cc6$The Action Potential$cc6$, 'biology', 1, 70
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a6A$Swaps the excitatory EPSP effect for the inhibitory IPSP effect (hyperpolarization, away from threshold, less likely to fire)$a6A$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a6C$Correctly identifies depolarization but reverses the direction of the membrane-potential shift relative to threshold$a6C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a6D$Confuses moving Vm toward a fixed threshold with lowering the threshold value itself$a6D$ FROM q;

-- Q7 [Threshold, Depolarization & Summation | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub7$Threshold, Depolarization & Summation$sub7$, $qt7$A neuron sits just below its threshold of excitation when an inhibitory presynaptic neuron releases GABA onto its dendrites, opening Cl- channels and producing an IPSP. Relative to the moment before the IPSP arrives, this input changes the neuron's likelihood of firing an action potential in which way?$qt7$, $op7$[{"label": "A", "text": "It hyperpolarizes the membrane, and because Vm was already near threshold, it pushes Vm past threshold and triggers an action potential."}, {"label": "B", "text": "It depolarizes the membrane more slowly than an excitatory input would, so the neuron still fires but with a delayed action potential."}, {"label": "C", "text": "It hyperpolarizes the membrane, moving Vm farther from threshold, so the neuron becomes less likely to fire an action potential."}, {"label": "D", "text": "It lowers the peak voltage of the resulting action potential, producing a smaller-amplitude action potential."}]$op7$::jsonb, 'C', $ex7$This is a Biology question that falls under the content category 'The Action Potential'. The answer is C because an inhibitory postsynaptic potential hyperpolarizes the membrane, which drives the membrane potential away from threshold and therefore reduces the probability that the neuron will reach threshold and fire. The Anatomy & Physiology text states that "Hyperpolarization in a postsynaptic potential is an inhibitory postsynaptic potential (IPSP) because it causes the membrane potential to move away from threshold," and the Biology text explains that when GABA is released it "binds to and opens Cl- channels. Cl- ions enter the cell and hyperpolarizes the membrane, making the neuron less likely to fire an action potential." Because reaching threshold (e.g., depolarizing from -70 mV toward -55 mV) is what triggers an action potential, any input that moves Vm in the opposite, more-negative direction makes that crossing harder to achieve. (Choice A) is wrong because hyperpolarization moves Vm away from threshold, not toward it, so it cannot push a near-threshold cell over the threshold or trigger firing. (Choice B) is wrong because an IPSP hyperpolarizes rather than depolarizes the membrane; inhibition is not simply a slower form of excitation, so it does not produce a merely delayed action potential. (Choice C) is correct because the IPSP-driven hyperpolarization moves Vm farther from threshold and lowers firing probability. (Choice D) is wrong because action potentials are "all or none"—a stronger or weaker stimulus does not make a "bigger" or smaller action potential, and all action potentials peak at the same voltage, so an IPSP cannot reduce action-potential amplitude. This is a Scientific Reasoning and Problem Solving question because it requires predicting the functional consequence (firing probability) of an ionic event (Cl- influx and hyperpolarization) on a neuron poised near threshold, rather than recalling a definition.$ex7$, 'medium', '3A', $cc7$The Action Potential$cc7$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a7A$pairs correct hyperpolarization with a firing outcome that contradicts moving away from threshold$a7A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a7B$treats inhibition as a weak/slow form of depolarization rather than hyperpolarization$a7B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a7D$invokes a graded-amplitude action potential, ignoring the all-or-none rule and the away-from-threshold effect$a7D$ FROM q;

-- Q8 [Threshold, Depolarization & Summation | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub8$Threshold, Depolarization & Summation$sub8$, $qt8$A neuron simultaneously receives excitatory postsynaptic potentials at four dendritic synapses positioned on opposite sides of its cell body, and the resulting depolarizations add together at the axon hillock to reach threshold and trigger an action potential. The mode of integration responsible for reaching threshold in this scenario is BEST identified as:$qt8$, $op8$[{"label": "A", "text": "temporal summation, because the combined depolarization results from inputs arriving at the same synaptic site separated by short time intervals"}, {"label": "B", "text": "saltatory conduction, because the depolarization jumps between separate sites and adds up as it spreads toward the trigger zone"}, {"label": "C", "text": "the refractory period, because the inputs at the different sites must each wait their turn before they can be added together"}, {"label": "D", "text": "spatial summation, because graded potentials arriving at the same instant from several different input locations are added together at the axon hillock"}]$op8$::jsonb, 'D', $ex8$This is a Biology question that falls under the content category 'The Action Potential'. The answer is D because the defining feature of spatial summation is that graded potentials originating at multiple, separate input locations on the neuron are integrated together at the same instant. The text states that "Summation can be spatial or temporal, meaning it can be the result of multiple graded potentials at different locations on the neuron, or all at the same place but separated in time," and that "Spatial summation is related to associating the activity of multiple inputs to a neuron with each other." Because the scenario specifies four synapses at different positions whose depolarizations add together simultaneously at the initial segment, where "the axon hillock is essentially the initial segment of the axon, and it is where summation takes place," the integration is spatial rather than temporal. (Choice A) Temporal summation is the wrong key because it is "the relationship of multiple action potentials from a single cell" arriving at "the same place but separated in time," which does not match a many-locations, same-instant scenario. (Choice B) Saltatory conduction describes the "jumping of the action potential from one node to the next" along a myelinated axon, not the integration of synaptic inputs at the trigger zone. (Choice C) The refractory period is the interval after a spike "in which it cannot produce another action potential because its sodium channels will not open," a post-spike recovery state, not a mechanism for adding converging inputs. (Choice D) Spatial summation correctly names integration of simultaneous graded potentials from different input locations added together at the axon hillock. This is a Scientific Reasoning and Problem Solving question because it requires applying the defining criteria of summation modes to a specific scenario and predicting which mode accounts for the observed threshold-reaching integration.$ex8$, 'medium', '3A', $cc8$The Action Potential$cc8$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a8A$names the real partner process (temporal summation) but its defining feature, timing at one site, does not fit a many-locations scenario$a8A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a8B$substitutes node-to-node action-potential propagation (saltatory conduction) for synaptic input integration$a8B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a8C$invokes the post-spike recovery interval (refractory period) instead of input integration$a8C$ FROM q;

-- Q9 [Threshold, Depolarization & Summation | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub9$Threshold, Depolarization & Summation$sub9$, $qt9$A motor neuron receives a single excitatory presynaptic axon that fires a brief, rapid burst of action potentials, and the postsynaptic cell reaches threshold at the axon hillock and fires. When the same presynaptic axon delivers the identical number of action potentials but spaced far apart in time, the postsynaptic cell does not fire. Which mechanism best explains why only the rapid burst triggers an action potential?$qt9$, $op9$[{"label": "A", "text": "The EPSPs arrive close enough in time that each adds onto the residual depolarization left by the previous one before it decays, so their effects summate at the axon hillock and reach threshold."}, {"label": "B", "text": "The rapid stimulation makes each individual EPSP larger in amplitude, so a single one of the closely spaced EPSPs is now big enough to reach threshold on its own."}, {"label": "C", "text": "The closely spaced inputs arrive at many different dendritic locations at once, so their spatially separated depolarizations are integrated together to reach threshold."}, {"label": "D", "text": "The rapid firing raises the action-potential peak to a higher voltage, so the larger action potential reaches threshold where a slower train could not."}]$op9$::jsonb, 'A', $ex9$This is a Biology question that falls under the content category 'The Action Potential'. The answer is A because temporal summation occurs when repeated EPSPs from one input arrive before the prior EPSP has decayed, so their graded depolarizations add together at the axon hillock and carry the membrane to threshold. The text states that graded potential "changes can lead to the neuron reaching threshold if the changes add together, or summate," and defines temporal summation as "multiple action potentials from a single cell" that are "all at the same place but separated in time" (A&P 2e). Because the rapid burst delivers each EPSP onto the residual depolarization of the last one, the net change in membrane voltage builds past threshold; the same EPSPs spaced far apart each decay back toward rest before the next arrives, so the depolarizations never overlap and never sum. The text confirms that "it is the net change in postsynaptic membrane voltage that determines whether the postsynaptic cell has reached its threshold of excitation" and that summation "occurs at the axon hillock" (Biology 2e). (Choice A) is correct because overlapping, undecayed EPSPs from one rapidly firing input summate over time at the hillock to reach threshold. (Choice B) is wrong because individual EPSP amplitude per input is essentially fixed; rapid firing matters because the EPSPs overlap, not because each one becomes larger, so no single EPSP reaches threshold alone. (Choice C) is wrong because integrating depolarizations from many different locations describes spatial summation, whereas the scenario specifies one repeatedly firing input, making this temporal summation. (Choice D) is wrong because the action potential is all-or-nothing and its peak (~+40 mV) does not vary with input rate; whether threshold is reached is set by the subthreshold graded EPSPs, not by the height of the spike. This is a Scientific Reasoning and Problem Solving question because it requires predicting and explaining a difference in firing outcome between two stimulus timings by applying the mechanism of temporal summation to a specific scenario.$ex9$, 'hard', '3A', $cc9$The Action Potential$cc9$, 'biology', 2, 160
  ) RETURNING id
)
