SELECT id, 'A', 'adjacent_fact', $a23A$Invents an asymmetric Na+ channel distribution (channels only ahead of the impulse) instead of citing inactivation of channels that are present throughout the membrane$a23A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a23B$Substitutes the Na+/K+ pump's slow gradient restoration for the fast Na+-channel inactivation that actually causes the absolute refractory block$a23B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a23D$Attributes directionality to myelin insulation of trailing membrane rather than to the refractory period, ignoring that the axon is unmyelinated$a23D$ FROM q;

-- Q24 [Refractory Periods | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub24$Refractory Periods$sub24$, $qt24$A researcher records the membrane voltage of a single neuron immediately after it fires an action potential and wants to identify the moment the cell enters its relative refractory period. Which recorded value indicates that the membrane is in the relative refractory period?$qt24$, $op24$[{"label": "A", "text": "A reading of +30 mV, captured when an influx of Na+ has driven the membrane to the peak of depolarization"}, {"label": "B", "text": "A reading of 0 mV, captured when the membrane has lost its charge separation and holds no net potential"}, {"label": "C", "text": "A reading of -45 mV, captured when the membrane is depolarized to a value above the firing threshold"}, {"label": "D", "text": "A reading of -80 mV, captured when continued K+ efflux has driven the membrane below its resting value"}]$op24$::jsonb, 'D', $ex24$This is a Biology question that falls under the content category 'The Action Potential'. The answer is D because the relative refractory period coincides with hyperpolarization, when the membrane voltage is transiently more negative than the -70 mV resting potential. As repolarization finishes, the slow-closing voltage-gated K+ channels let K+ continue to leave the cell, so the diffusion of K+ "continues for a short period of time past the time of the achievement of the resting potential, and the membrane hyperpolarizes, in that the membrane potential becomes more negative than the cell's normal resting potential" (Biology 2e). During this window "the hyperpolarized membrane is in a refractory period," and a reading of -80 mV — below the roughly -70 mV rest — is the only value consistent with that hyperpolarized state. The relative period is also when "only ... a stronger stimulus" can fire the cell because outward K+ flow opposes depolarization (Anatomy & Physiology 2e). (Choice A) +30 mV is the peak of depolarization driven by Na+ influx, which falls in the absolute refractory period when Na+ channels are inactivated, not the relative period. (Choice B) 0 mV would imply the membrane has no charge separation, but the membrane is never charge-neutral during recovery; it is repolarizing and then hyperpolarizing past rest. (Choice C) -45 mV is above threshold and more positive than the resting potential, describing a depolarized membrane rather than the hyperpolarized state of the relative refractory period. (Choice D) -80 mV reflects the membrane driven more negative than rest by ongoing K+ efflux, the defining signature of the relative refractory period. This is a Scientific Reasoning and Problem Solving question because it requires interpreting recorded voltage data and reasoning from the underlying ion-flux mechanism to identify which value matches the hyperpolarized relative refractory period.$ex24$, 'hard', '3A', $cc24$The Action Potential$cc24$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a24A$Confusing the peak depolarization step (absolute period) with the later hyperpolarized relative period$a24A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a24B$Treating the recovering membrane as a fully discharged, charge-neutral (0 mV) state$a24B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a24C$Plausible above-threshold value that is more positive than rest rather than hyperpolarized below it$a24C$ FROM q;

-- Q25 [Refractory Periods | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub25$Refractory Periods$sub25$, $qt25$A neurotoxin binds the voltage-gated Na+ channels of a sensory neuron and locks their inactivation gates in the closed (inactivated) conformation, so the gates take far longer than normal to re-open after each action potential. A physiologist records from the treated neuron during a sustained, suprathreshold stimulus and compares it to an untreated control. What does the physiologist most likely observe in the treated neuron?$qt25$, $op25$[{"label": "A", "text": "A lower maximum firing frequency, because the lengthened absolute refractory period delays when a new action potential can be generated"}, {"label": "B", "text": "A higher maximum firing frequency, because the Na+ channels spend more time available to reopen between action potentials"}, {"label": "C", "text": "Action potentials of smaller amplitude at the same firing frequency, because reduced Na+ influx shrinks each spike without altering its timing"}, {"label": "D", "text": "A resting membrane potential that drifts more positive, because the trapped Na+ channels leak Na+ inward while the cell is at rest"}]$op25$::jsonb, 'A', $ex25$This is a Biology question that falls under the content category 'The Action Potential'. The answer is A because the absolute refractory period exists specifically while the Na+ channel inactivation gates are closed, and a new action potential cannot be initiated until those gates re-open. The A&P text states that during the absolute phase "another action potential will not start. This is because of the inactivation gate of the voltage-gated Na+ channel," and that only after the inactivation gate re-opens is the channel "ready to start the whole process over again." A toxin that keeps the inactivation gates closed for an extended time therefore lengthens the absolute refractory period, so a longer interval must pass before the membrane can fire again; because firing rate is set by how quickly the neuron recovers between spikes, the maximum firing frequency falls. (Choice A) is correct: a prolonged inactivated state lengthens the absolute refractory period and reduces the maximum number of action potentials per unit time. (Choice B) reverses the relationship—keeping inactivation gates closed makes the channels less available, not more, so firing frequency drops rather than rises. (Choice C) is a partial truth that fails because action potentials are "all or none" and "all action potentials peak at the same voltage (+30 mV)," so the toxin alters refractory timing, not spike amplitude. (Choice D) is a misconception, because an inactivated channel is closed to ion flux rather than leaking Na+ inward, and the resting potential is set by non-gated channels and the Na+/K+ pump, so resting Vm does not drift positive. This is a Scientific Reasoning and Problem Solving question because it requires predicting the functional consequence of a specific molecular perturbation by tracing the effect of prolonged Na+-channel inactivation through the refractory period to the neuron's maximum firing frequency.$ex25$, 'hard', '3A', $cc25$The Action Potential$cc25$, 'biology', 2, 160
  ) RETURNING id
)
