UNION ALL SELECT id, 'C', 'partial_truth', $a25C$Correctly notes reduced Na+ influx but mislocates the effect to spike amplitude, ignoring the all-or-none nature of the action potential and the real effect on refractory timing$a25C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a25D$Imagines an inactivated channel as a leaky open pore shifting resting Vm, when inactivated channels conduct no flux and resting potential depends on non-gated channels and the Na+/K+ pump$a25D$ FROM q;

